def _check_region_wide_batch_entry(
    entry: object, name: str = "entry"
) -> RegionWideBatchEntry:
    """Validate one RegionWideBatchEntry and its nested field types."""
    if not isinstance(entry, RegionWideBatchEntry):
        raise TypeError(f"{name} must be a RegionWideBatchEntry")
    x_commitment = entry.x_commitment
    y_commitment = entry.y_commitment
    region = entry.region
    proof = entry.proof
    if not isinstance(x_commitment, PedersenCommitment):
        raise TypeError(f"{name} x_commitment must be a PedersenCommitment")
    if not isinstance(y_commitment, PedersenCommitment):
        raise TypeError(f"{name} y_commitment must be a PedersenCommitment")
    _check_commitment_fields(x_commitment)
    _check_commitment_fields(y_commitment)
    if not isinstance(region, Region):
        raise TypeError(f"{name} region must be a Region")
    _check_region_fields(region)
    if not isinstance(proof, RegionWideProof):
        raise TypeError(f"{name} proof must be a RegionWideProof")
    for axis_name, sub_proof in (("x", proof.x_proof), ("y", proof.y_proof)):
        if not isinstance(sub_proof, WideRangeProof):
            raise TypeError(
                f"{name} proof {axis_name}_proof must be a WideRangeProof"
            )
        if not isinstance(sub_proof.commitments, tuple):
            raise TypeError(
                f"{name} proof {axis_name}_proof commitments must be a tuple "
                "of integers"
            )
        for item in sub_proof.commitments:
            _check_int(item, f"{name} proof {axis_name}_proof commitments entry")
        for field_name in ("challenges", "responses"):
            field = getattr(sub_proof, field_name)
            if not isinstance(field, tuple):
                raise TypeError(
                    f"{name} proof {axis_name}_proof {field_name} must be a "
                    "tuple of integer pairs"
                )
            for pair in field:
                if not isinstance(pair, tuple):
                    raise TypeError(
                        f"{name} proof {axis_name}_proof {field_name} entry "
                        "must be a tuple of integers"
                    )
                for item in pair:
                    _check_int(
                        item,
                        f"{name} proof {axis_name}_proof {field_name} entry item",
                    )
    _check_bytes(entry.context, f"{name} context")
    return entry


